import {describe, it, expect} from 'vitest';
import {createChatOrchestrator} from './chatOrchestrator.js';
import type {OrchestratorHooks} from './chatOrchestrator.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import type {AIProvider, MessageChunk, UsageMetadata} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';
import {ToolRegistry} from './tools/registry.js';

const promptBuilder = new PromptBuilder({identity: 'Usage test.'});
const session = (): ChatSession => ({
  sessionId: 's',
  userId: 'u',
  entries: [{role: 'user', content: 'Go.', timestamp: '2026-01-01T00:00:00.000Z'}],
});

const TOOL_CALL: MessageChunk = {type: 'tool_use', toolCall: {id: 'c1', name: 't', input: {}}};
const usageStop = (stopReason: string, usage?: UsageMetadata): MessageChunk => ({type: 'stop', stopReason, usage});

const scriptedProvider = (rounds: MessageChunk[][]): AIProvider => {
  let round = 0;
  return {
    async *sendMessage(): AsyncGenerator<MessageChunk> {
      yield* rounds[round++] ?? [];
    },
    async generateStructured<T>(): Promise<T> {
      return {} as T;
    },
  };
};

const registry = (): ToolRegistry => {
  const r = new ToolRegistry();
  r.register({name: 't', description: 't', inputSchema: {type: 'object'}}, async () => 'ok');
  return r;
};

describe('ChatOrchestrator usage aggregation', () => {
  it('reports summed usage in a TurnUsage contract', async () => {
    let reported: any;
    const hooks: OrchestratorHooks = {
      afterModelResponse: async (_session, _text, usage) => {
        reported = usage;
      },
    };

    const orchestrator = createChatOrchestrator(
      scriptedProvider([
        [TOOL_CALL, usageStop('tool_use', {inputTokens: 10, outputTokens: 2, totalTokens: 12})],
        [{type: 'text', text: 'Done.'}, usageStop('end_turn', {inputTokens: 20, outputTokens: 5, totalTokens: 25})],
      ]),
      promptBuilder,
      registry(),
      {hooks}
    );

    await orchestrator.processMessage(session());

    // Expecting the new structure as per "deliberately named total-usage contract whose public type makes aggregation explicit"
    // I'll assume for now it's { total: UsageMetadata } or similar. 
    // Let's try to be consistent with the idea of making it explicit.
    expect(reported).toEqual({
      inputTokens: 30,
      outputTokens: 7,
      totalTokens: 37
    });
  });
});

